import React from 'react';
import { FormStep, Input, FormItem } from '@storage-fe/formily-arco';
import { createForm } from '@formily/core';
import { Field, FormProvider, VoidField } from '@formily/react';
import { Button, Space } from '@arco-design/web-react';
import { IFormStep } from '../types';

const sleep = async (time: number) => new Promise(resolve => setTimeout(() => {
  resolve(1);
}, time)
);

const form = createForm();
const formStep = FormStep.createFormStep();
const { StepPane, FooterSlot, ResidentContentSlot, TopSlot, HeaderSlot } = FormStep;

export default () => (
  <FormProvider form={form}>
    <VoidField
      name="formStep" component={[FormStep, {
        formStep, mode: 'JSX', beforeStepChange: async () => {
          await sleep(1000);
          return true;
        }
      }]}>
      <VoidField name="headerSlot" component={[HeaderSlot]}>
        <div>顶部Header</div>
      </VoidField>
      <VoidField name="topSlot" component={[TopSlot]}>
        <div style={{ margin: 20 }}>顶部插入内容：这是一个顶部标题</div>
      </VoidField>
      <VoidField name="first" component={[StepPane, { title: '第一步' }]}>
        <Field name="aaa" component={[Input]} decorator={[FormItem, { label: 'AAA' }]} />
        <Field
          name="bbb"
          component={[Input]}
          required={true}
          decorator={[FormItem, { label: 'BBB', required: true }]}
        />
      </VoidField>
      <VoidField name="second" component={[StepPane, { title: '第二步' }]}>
        <Field name="ccc" component={[Input]} decorator={[FormItem, { label: 'CCC' }]} />
        <Field
          name="ddd"
          component={[Input]}
          required={true}
          decorator={[FormItem, { label: 'DDD', required: true }]}
        />
      </VoidField>
      <VoidField name="third" component={[StepPane, { title: '第三步' }]}>
        <Field name="ppp" component={[Input]} decorator={[FormItem, { label: 'PPP' }]} />
        <Field
          name="qqq"
          component={[Input]}
          required={true}
          decorator={[FormItem, { label: 'QQQ', required: true }]}
        />
      </VoidField>
      <VoidField name="resident" component={[ResidentContentSlot]}>
        <Field name="zzz" component={[Input]} decorator={[FormItem, { label: '常驻字段' }]} />
      </VoidField>
      <VoidField name="footer" component={[FooterSlot]}>
        {(formStep: IFormStep) => (
          <Space align="end" size={'medium'}>
            <FormStep.BackButton />
            <FormStep.NextButton />
            {!formStep.allowNext && <FormStep.SubmitButton onSubmit={async () => await sleep(1000)} />}
          </Space>
        )}
      </VoidField>
    </VoidField>
  </FormProvider>
);
